      (function () {
        try {
          var mode = localStorage.getItem('tbf_theme');
          if (mode) mode = JSON.parse(mode);
        } catch (e) {
          mode = null;
        }
        var resolved =
          mode === 'light' || mode === 'dark'
            ? mode
            : mode === 'auto' &&
                window.matchMedia('(prefers-color-scheme: light)').matches
              ? 'light'
              : mode === 'auto'
                ? 'dark'
                : 'dark';
